// Standard C++: 'inline' is a compiler hint (weak linkage requirement)
inline int small_op(int x, int y) {
    return x * x + y;
}

// Compiler mandate (GCC/Clang specific: forces inlining unless impossible)
// Use judiciously: Can lead to code bloat (I-cache misses)
__attribute__((always_inline))
int fast_op(int x) {
    return x << 2;
}

// Standard C++: Often automatically inlined if defined in class body
class Processor {
public:
    int add(int a, int b) const {
        return a + b;
    }
};

// Virtual functions are rarely inlined due to dynamic dispatch overhead
class Base {
    virtual int calculate(int x) = 0;
};

// External, large function definition: Compiler will usually ignore 'inline' hint
void large_function(int* data);
// Compiler heuristics consider function size, call frequency, optimization level (-O3)
// Recurrence/Recursion usually prevents inlining
// Exception handling often prevents inlining
// Dynamic linking prevents cross-module inlining
// LTO (Link Time Optimization) allows broader inlining decisions
// PGO (Profile Guided Optimization) informs better inlining decisions
// Stack frame size reduction is a key benefit
// Instruction cache pressure is a key downside
// Compiler must balance code size vs. speed
